// Heartbeat sends minimal event-specific bodies and does not consistently
// include the configured action name. Classify only documented shapes and
// reject everything else before it reaches Tandem.

const raw = $input.first().json;
const body = raw.body || raw;
const data = body.data && typeof body.data === 'object' ? body.data : body;
const explicit = String(body?.action?.name || body?.event || '').toUpperCase();
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const email = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

let event = explicit;
if (!event) {
  if (data.courseID && data.userID) event = 'COURSE_COMPLETED';
  else if (data.groupID && data.userID) event = 'GROUP_JOIN';
  else if (data.invitationLinkID && data.email && Array.isArray(data.groupIDs)) event = 'ABANDONED_CART';
  else if (data.id && data.email) event = 'USER_JOIN';
}

const valid = {
  COURSE_COMPLETED: uuid.test(String(data.courseID || '')) && uuid.test(String(data.userID || '')),
  GROUP_JOIN: uuid.test(String(data.groupID || '')) && uuid.test(String(data.userID || '')),
  USER_JOIN: uuid.test(String(data.id || '')) && email.test(String(data.email || '')),
  ABANDONED_CART:
    email.test(String(data.email || '')) &&
    typeof data.invitationLinkID === 'string' &&
    data.invitationLinkID.length > 0 &&
    Array.isArray(data.groupIDs) &&
    data.groupIDs.length > 0 &&
    data.groupIDs.every((id) => uuid.test(String(id))),
};

if (!Object.prototype.hasOwnProperty.call(valid, event) || !valid[event]) {
  throw new Error(`Rejected undocumented Heartbeat payload shape (${event || 'unknown'})`);
}

return [{ json: { event, data, received_at: new Date().toISOString() } }];
